package com.nth.desktop3d;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;

/** Native dock-aware fading, contextual surfaces, signed padding and folder flick regressions. */
public final class Interaction081Smoke {
    private final Instrumentation test;private final MainActivity activity;private final String output;private SettingsModel model;private LauncherStore store;private LauncherStore.Item first,second;
    public Interaction081Smoke(Instrumentation t,MainActivity a,String o){test=t;activity=a;output=o;}
    public void run()throws Exception {
        model=(SettingsModel)value("settingsModel",new Class[]{});store=model.store;JSONObject before=DesktopBackup.capture(activity,model);boolean feed=model.crystal.feedEnabled();
        try{
            main(()->{store.page=0;store.mode=3;for(int p=0;p<2;p++){store.pages.get(p).clear();LauncherStore.Item folder=new LauncherStore.Item("folder",p==0?"Flick folder":"Return folder");folder.cellX=1;folder.cellY=1;for(int i=0;i<20;i++)folder.children.add(new LauncherStore.Item("builtin:notes","Note "+i));store.pages.get(p).add(folder);if(p==0)first=folder;else second=folder;store.preferences.edit().putBoolean("folder_pattern_page_"+p,false).apply();}store.preferences.edit().putInt("desktop_padding",0).putInt("dock_padding",0).putInt("gesture_left",4).putInt("gesture_right",4).putBoolean("show_dock",true).putBoolean("dock_content",true).apply();store.dock.item(0,first);store.dock.item(1,new LauncherStore.Item("builtin:settings","Settings"));model.crystal.setFeedEnabled(false);model.set("reduced_motion",1);model.set("wallpaper_source",0);model.set("adaptive_glass",1);model.set("glass_strength",90);model.set("glass_feather",12);model.set("glass_empty",0);store.save();call("applySettings",new Class[]{boolean.class},true);});idle(500);
            fading();menus();padding();gestures();
        }finally{main(()->{try{call("closePanel",new Class[]{});model.importDesktopBackup(activity,new DesktopBackup.Prepared(before,model));model.crystal.setFeedEnabled(feed);}catch(Exception e){throw new AssertionError(e);}});}
    }
    @SuppressWarnings("unchecked") private void fading(){invoke("showFolder",new Class[]{LauncherStore.Item.class},first);idle(450);main(()->{View panel=(View)field("panel"),dock=(View)field("dockContents");View slot=((ViewGroup)dock).getChildAt(0);int[] p=new int[2],d=new int[2];panel.getLocationOnScreen(p);slot.getLocationOnScreen(d);float x=d[0]+slot.getWidth()/2f-p[0],y=d[1]+slot.getHeight()/2f-p[1];check(x>=0&&x<panel.getWidth()&&y>=0&&y<panel.getHeight(),"Fixture dock does not overlap menu");List<RectF> boxes=(List<RectF>)call("menuBackdrops",new Class[]{View.class},panel);check(AdaptiveOpacity.coverage(x,y,array(boxes),1)>.95,"Dock content missing from fading geometry");AdaptiveMenuDrawable glass=(AdaptiveMenuDrawable)panel.getBackground();glass.update(boxes,90,12,0,true,.1f);Bitmap image=Bitmap.createBitmap(panel.getWidth(),panel.getHeight(),Bitmap.Config.ARGB_8888);try{glass.draw(new Canvas(image));check(Color.alpha(image.getPixel(Math.round(x),Math.round(y)))>210,"Menu remained transparent over dock content");}finally{image.recycle();}});capture("081-folder-fades-over-dock");}
    private float[][] array(List<RectF> boxes){float[][] out=new float[boxes.size()][4];for(int i=0;i<out.length;i++){RectF r=boxes.get(i);out[i]=new float[]{r.left,r.top,r.right,r.bottom};}return out;}
    private void menus(){Object previous=field("panel");invoke("showAreaSettings",new Class[]{});idle(450);main(()->{AlertDialog dialog=(AlertDialog)field("areaMenu");View body=(View)field("areaMenuBody");check(dialog!=null&&dialog.isShowing()&&body.getBackground() instanceof AdaptiveMenuDrawable,"Three-dot menu does not use fading surface");check(((View)previous).getVisibility()==View.INVISIBLE,"Parent menu is competing with contextual menu text");check((dialog.getWindow().getAttributes().flags&android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND)==0,"Context menu added a separate dim layer");check(find(dialog.getWindow().getDecorView(),"Folder columns")!=null,"Context menu lost folder controls");});capture("081-fading-three-dot-menu");main(()->((AlertDialog)field("areaMenu")).dismiss());check(field("panel")==previous,"Dismissing contextual menu rebuilt its parent");main(()->check(((View)previous).getVisibility()==View.VISIBLE,"Closing contextual menu did not restore parent"));
        invoke("showSettings",new Class[]{String.class},"nota");Object studio=field("settingsStudio");main(()->find(activity.getWindow().getDecorView(),"Conversation menu").performClick());systemClick("Command examples");idle(350);main(()->{check(((View)field("areaMenuBody")).getBackground() instanceof AdaptiveMenuDrawable,"Nota examples use a different menu surface");AlertDialog d=(AlertDialog)field("areaMenu");View command=find(d.getWindow().getDecorView(),"set Desktop side padding to -50");check(command!=null,"Signed padding example missing");command.performClick();check(field("settingsStudio")==studio,"Example menu destroyed the question screen");});invoke("closePanel",new Class[]{});}
    private void padding()throws Exception {
        check(model.specs.get("desktop_padding").min==-50&&model.specs.get("desktop_padding").max==50&&model.specs.get("dock_padding").min==-50&&model.specs.get("dock_padding").max==50,"Padding slider is not centered around zero");
        invoke("showSettings",new Class[]{String.class},"home");main(()->((SettingsStudio)field("settingsStudio")).focusSetting("desktop_padding"));setPaddingSlider(0);int wide=desktop().getWidth();setPaddingSlider(100);check(desktop().getWidth()<wide-Ui.dp(activity,40),"Negative padding did not widen desktop");main(()->{View shell=(View)field("shell");check(shell.getPaddingLeft()>=0&&shell.getPaddingRight()>=0,"Padding escaped physical screen");});capture("081-signed-padding");invoke("closePanel",new Class[]{});
        main(()->{model.set("dock_padding",-50);check(((View)field("dock")).getPaddingLeft()==0,"Negative dock padding did not expand content");model.set("dock_padding",50);check(((View)field("dock")).getPaddingLeft()>Ui.dp(activity,8),"Positive dock padding did not add spacing");model.set("dock_padding",0);model.set("desktop_padding",0);});
        JSONObject old=model.exportSettings();old.remove("paddingOffsets");old.getJSONObject("values").put("dock_padding",7);main(()->{try{model.importSettings(old);}catch(Exception e){throw new AssertionError(e);}});check(model.value("dock_padding")==0&&old.getJSONObject("values").getInt("dock_padding")==7,"Legacy padding migration shifted neutral spacing or mutated source");
        main(()->model.set("dock_padding",-3));JSONObject saved=model.exportSettings();main(()->{try{model.set("dock_padding",10);model.importSettings(saved);}catch(Exception e){throw new AssertionError(e);}});check(model.value("dock_padding")==-3,"Signed settings did not restore unchanged");JSONObject backup=DesktopBackup.capture(activity,model);main(()->{try{model.importDesktopBackup(activity,new DesktopBackup.Prepared(backup,model));}catch(Exception e){throw new AssertionError(e);}});check(model.value("dock_padding")==-3,"Full backup lost signed padding");main(()->model.set("dock_padding",0));
    }
    private void setPaddingSlider(int value){main(()->{View view=find(activity.getWindow().getDecorView(),"Desktop side padding");SeekBar bar=findSlider(activity.getWindow().getDecorView(),"Desktop side padding");check(bar!=null,"Padding slider missing");Bundle args=new Bundle();args.putFloat("android.view.accessibility.action.ARGUMENT_PROGRESS_VALUE",value);check(bar.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),args),"Padding slider rejected native input");});idle(350);}
    private void gestures(){invoke("closePanel",new Class[]{});main(()->{store.page=0;store.save();desktop().rebuild();});idle(350);swipe(first,-36,48);check(store.page==1&&field("overlay")==null,"Fast short flick over folder did not change desktop");swipe(second,36,48);check(store.page==0&&field("overlay")==null,"Right flick over folder did not return desktop");swipe(first,-36,350);check(store.page==0&&field("overlay")==null,"Slow short folder motion incorrectly became a fling");main(()->store.preferences.edit().putInt("gesture_left",1).apply());swipe(first,-100,250);check(field("settingsStudio")!=null,"Folder swipe did not run assigned action");invoke("closePanel",new Class[]{});main(()->store.preferences.edit().putInt("gesture_left",4).apply());
        int[] p=location(tile(first));long now=SystemClock.uptimeMillis();inject(now,now,MotionEvent.ACTION_DOWN,p[0],p[1]);idle(ViewConfiguration.getLongPressTimeout()+100);inject(now,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,p[0],p[1]);idle(300);check(field("overlay")!=null&&store.page==0,"Stationary folder hold no longer opens its menu");capture("081-folder-hold-menu");invoke("closePanel",new Class[]{});
    }
    private void swipe(LauncherStore.Item item,float dxDp,int duration){int[] p=location(tile(item));float dx=Ui.dp(activity,dxDp);long now=SystemClock.uptimeMillis();inject(now,now,MotionEvent.ACTION_DOWN,p[0],p[1]);for(int i=1;i<=6;i++)inject(now,now+duration*i/6,MotionEvent.ACTION_MOVE,p[0]+dx*i/6,p[1]);inject(now,now+duration,MotionEvent.ACTION_UP,p[0]+dx,p[1]);idle(450);}
    private void inject(long down,long at,int action,float x,float y){MotionEvent e=MotionEvent.obtain(down,at,action,x,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);test.getUiAutomation().injectInputEvent(e,true);e.recycle();}
    @SuppressWarnings("unchecked") private View tile(LauncherStore.Item item){AtomicReference<View> out=new AtomicReference<>();main(()->{try{java.lang.reflect.Field f=DesktopView.class.getDeclaredField("cellViews");f.setAccessible(true);out.set(((Map<String,View>)f.get(desktop())).get(item.id));}catch(Exception e){throw new AssertionError(e);}});check(out.get()!=null,"Folder tile missing");return out.get();}
    private int[] location(View view){AtomicReference<int[]> r=new AtomicReference<>();main(()->{int[] p=new int[2];view.getLocationOnScreen(p);r.set(new int[]{p[0]+view.getWidth()/2,p[1]+view.getHeight()/2});});return r.get();}
    private SeekBar findSlider(View v,String text){if(v instanceof SeekBar&&text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return (SeekBar)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){SeekBar found=findSlider(((ViewGroup)v).getChildAt(i),text);if(found!=null)return found;}return null;}
    private View find(View v,String text){if(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),text);if(f!=null)return f;}return null;}
    private DesktopView desktop(){return (DesktopView)field("desktop");}
    private Object field(String name){try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new AssertionError(e);}}
    private Object call(String name,Class<?>[] types,Object...args){try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}catch(Exception e){throw new AssertionError(e);}}
    private Object value(String name,Class<?>[] types,Object...args){AtomicReference<Object> r=new AtomicReference<>();main(()->r.set(call(name,types,args)));return r.get();}
    private void invoke(String name,Class<?>[] types,Object...args){main(()->call(name,types,args));idle(250);}
    private void main(Runnable r){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{r.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void systemClick(String text){long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){android.view.accessibility.AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root!=null)for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(text))if(text.contentEquals(node.getText()==null?"":node.getText())){android.view.accessibility.AccessibilityNodeInfo target=node;while(target!=null){if(target.isClickable()&&target.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){idle(300);return;}target=target.getParent();}}idle(100);}throw new AssertionError("Dialog action missing: "+text);}
    private void idle(long ms){SystemClock.sleep(ms);test.runOnMainSync(()->{});}
    private void capture(String name){idle(250);Bitmap b=test.getUiAutomation().takeScreenshot();File dir=output==null?new File(activity.getExternalFilesDir(null),"verification"):new File(output);dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{b.recycle();}}
    private static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
}
